using System;
using System.Collections.Generic;
using System.Collections.ObjectModel;

namespace Framework.AI.Decision
{
    /// <summary>
    /// 複数の行動候補を評価し、最適な行動を選択する。
    /// </summary>
    /// <typeparam name="TAction">行動識別子の型</typeparam>
    /// <typeparam name="TContext">意思決定情報の型</typeparam>
    /// <remarks>
    /// 行動の実行状態は管理しない。
    /// 評価中に行動候補を変更することはできない。
    /// </remarks>
    public sealed class UtilitySelector<TAction, TContext>
    {
        /// <summary>
        /// 登録された行動候補。
        /// </summary>
        private readonly List<UtilityOption<TAction, TContext>>
            options =
                new List<UtilityOption<TAction, TContext>>();

        /// <summary>
        /// 直近の意思決定における評価結果。
        /// </summary>
        private readonly List<UtilityEvaluation<TAction>>
            evaluations =
                new List<UtilityEvaluation<TAction>>();

        /// <summary>
        /// 評価結果の読み取り専用コレクション。
        /// </summary>
        private readonly ReadOnlyCollection<
            UtilityEvaluation<TAction>> readOnlyEvaluations;

        /// <summary>
        /// 行動識別子の比較処理。
        /// </summary>
        private readonly EqualityComparer<TAction> comparer =
            EqualityComparer<TAction>.Default;

        /// <summary>
        /// 現在評価処理を実行しているかどうか。
        /// </summary>
        private bool isEvaluating;

        /// <summary>
        /// 現在の行動に適用する継続優遇値。
        /// </summary>
        private float continuationBonus;

        /// <summary>
        /// 登録された行動候補数を取得する。
        /// </summary>
        public int Count => options.Count;

        /// <summary>
        /// 現在の継続優遇値を取得する。
        /// </summary>
        public float ContinuationBonus => continuationBonus;

        /// <summary>
        /// 直近の評価結果を取得する。
        /// </summary>
        /// <remarks>
        /// 次回の評価時に内容が更新される。
        /// </remarks>
        public IReadOnlyList<UtilityEvaluation<TAction>>
            LastEvaluations => readOnlyEvaluations;

        /// <summary>
        /// 行動選択システムを生成する。
        /// </summary>
        /// <param name="continuationBonus">継続優遇値</param>
        public UtilitySelector(
            float continuationBonus = 0.1f)
        {
            readOnlyEvaluations = evaluations.AsReadOnly();

            SetContinuationBonus(continuationBonus);
        }

        /// <summary>
        /// 継続優遇値を変更する。
        /// </summary>
        /// <param name="value">継続優遇値。0から1</param>
        public void SetContinuationBonus(float value)
        {
            EnsureNotEvaluating();

            if (float.IsNaN(value) ||
                float.IsInfinity(value) ||
                value < 0f ||
                value > 1f)
            {
                throw new ArgumentOutOfRangeException(
                    nameof(value));
            }

            continuationBonus = value;
        }

        /// <summary>
        /// 行動候補を登録する。
        /// </summary>
        /// <param name="option">登録する行動候補</param>
        /// <returns>登録に成功した場合はtrue</returns>
        public bool TryAddOption(
            UtilityOption<TAction, TContext> option)
        {
            EnsureNotEvaluating();

            if (option == null)
            {
                throw new ArgumentNullException(nameof(option));
            }

            if (HasOption(option.Id))
            {
                return false;
            }

            options.Add(option);

            // 構成変更前の評価結果を無効化する。
            evaluations.Clear();

            return true;
        }

        /// <summary>
        /// 指定された行動候補が登録されているか判定する。
        /// </summary>
        /// <param name="actionId">行動識別子</param>
        /// <returns>登録されている場合はtrue</returns>
        public bool HasOption(TAction actionId)
        {
            for (int i = 0; i < options.Count; i++)
            {
                if (comparer.Equals(options[i].Id, actionId))
                {
                    return true;
                }
            }

            return false;
        }

        /// <summary>
        /// 指定された行動候補を削除する。
        /// </summary>
        /// <param name="actionId">行動識別子</param>
        /// <returns>削除に成功した場合はtrue</returns>
        public bool TryRemoveOption(TAction actionId)
        {
            EnsureNotEvaluating();

            for (int i = 0; i < options.Count; i++)
            {
                if (comparer.Equals(options[i].Id, actionId))
                {
                    options.RemoveAt(i);
                    evaluations.Clear();

                    return true;
                }
            }

            return false;
        }

        /// <summary>
        /// すべての行動候補と評価結果を削除する。
        /// </summary>
        public void Clear()
        {
            EnsureNotEvaluating();

            options.Clear();
            evaluations.Clear();
        }

        /// <summary>
        /// 現在の行動が存在しない状態で行動を選択する。
        /// </summary>
        /// <param name="context">意思決定情報</param>
        /// <param name="selected">選択された評価結果</param>
        /// <returns>有効な行動が選択された場合はtrue</returns>
        public bool TrySelect(
            TContext context,
            out UtilityEvaluation<TAction> selected)
        {
            return SelectInternal(
                context,
                false,
                default(TAction),
                out selected);
        }

        /// <summary>
        /// 現在の行動を考慮して行動を選択する。
        /// </summary>
        /// <param name="context">意思決定情報</param>
        /// <param name="currentActionId">現在の行動識別子</param>
        /// <param name="selected">選択された評価結果</param>
        /// <returns>有効な行動が選択された場合はtrue</returns>
        public bool TrySelect(
            TContext context,
            TAction currentActionId,
            out UtilityEvaluation<TAction> selected)
        {
            return SelectInternal(
                context,
                true,
                currentActionId,
                out selected);
        }

        /// <summary>
        /// 登録された行動候補を評価して選択する。
        /// </summary>
        /// <param name="context">意思決定情報</param>
        /// <param name="hasCurrentAction">現在の行動が存在するか</param>
        /// <param name="currentActionId">現在の行動識別子</param>
        /// <param name="selected">選択された評価結果</param>
        /// <returns>有効な行動が選択された場合はtrue</returns>
        private bool SelectInternal(
            TContext context,
            bool hasCurrentAction,
            TAction currentActionId,
            out UtilityEvaluation<TAction> selected)
        {
            EnsureNotEvaluating();

            selected = default(UtilityEvaluation<TAction>);

            evaluations.Clear();

            isEvaluating = true;

            try
            {
                for (int i = 0; i < options.Count; i++)
                {
                    var option = options[i];

                    bool isCurrent =
                        hasCurrentAction &&
                        comparer.Equals(
                            option.Id,
                            currentActionId);

                    float score = option.Evaluate(context);

                    var evaluation =
                        new UtilityEvaluation<TAction>(
                            option.Id,
                            score,
                            isCurrent,
                            continuationBonus);

                    // デバッグ用に評価値0の結果も保持する。
                    evaluations.Add(evaluation);

                    if (!evaluation.IsSelectable)
                    {
                        continue;
                    }

                    // 評価値が同じ場合は現在の行動を優先する。
                    // それ以外の同点は登録順を維持する。
                    if (!selected.IsValid ||
                        evaluation.SelectionScore >
                            selected.SelectionScore ||
                        (evaluation.SelectionScore ==
                            selected.SelectionScore &&
                         evaluation.IsCurrentAction &&
                         !selected.IsCurrentAction))
                    {
                        selected = evaluation;
                    }
                }

                return selected.IsSelectable;
            }
            catch
            {
                // 不完全な評価結果を外部に残さない。
                evaluations.Clear();

                selected =
                    default(UtilityEvaluation<TAction>);

                throw;
            }
            finally
            {
                isEvaluating = false;
            }
        }

        /// <summary>
        /// 評価中の再入や構成変更を防止する。
        /// </summary>
        /// <exception cref="InvalidOperationException">
        /// 評価処理中に呼び出された場合に発生する。
        /// </exception>
        private void EnsureNotEvaluating()
        {
            if (isEvaluating)
            {
                throw new InvalidOperationException(
                    "行動評価中はこの操作を実行できません。");
            }
        }
    }
}
